c.java:
class Solution {
    public int addedInteger(int[] nums1, int[] nums2) {
        int a = Integer.MAX_VALUE, b = Integer.MAX_VALUE;
        for (int v : nums1) a = Math.min(a, v);
        for (int v : nums2) b = Math.min(b, v);
        return b - a;
    }
}

